import sys, json
src, out = sys.argv[1], sys.argv[2]
with open(src, encoding='utf-8', errors='replace') as f, open(out, 'w') as o:
    for n, line in enumerate(f, 1):
        try:
            r = json.loads(line)
        except Exception:
            continue
        t = r.get('type'); ts = r.get('timestamp', '')
        if r.get('isSidechain'): continue
        if t == 'queue-operation' and r.get('operation') == 'enqueue':
            c = r.get('content')
            if isinstance(c, str):
                o.write(f"{n}\t{ts}\tQ\t-\t{c}\n".replace('\r',''))
            continue
        m = r.get('message') or {}
        if t == 'user':
            c = m.get('content')
            txt = None
            if isinstance(c, str): txt = c
            elif isinstance(c, list):
                parts = [b.get('text','') for b in c if isinstance(b, dict) and b.get('type') == 'text']
                if parts: txt = '\n'.join(parts)
            if txt:
                o.write(f"{n}\t{ts}\tU\t-\t{txt}\n")
        elif t == 'assistant':
            c = m.get('content')
            model = m.get('model', '-')
            if isinstance(c, list):
                parts = [b.get('text','') for b in c if isinstance(b, dict) and b.get('type') == 'text']
                if parts:
                    o.write(f"{n}\t{ts}\tA\t{model}\t" + '\n'.join(parts) + "\n")
EOF
